//
// Vermont income tax withholding: GB-1210-2026, "2026 Income Tax
// Withholding Instructions, Tables, and Charts", Vermont Percentage Method
// Withholding Tables (wages paid in 2026):
//   1. one allowance (from the table's footnote, e.g. $103.85 weekly) x
//      allowances claimed on Form W-4VT
//   2. subtract from wages
//   3. the period's single or married table (3.35% / 6.60% / 7.60% / 8.75%)
// Tables generated by tools/state/generate_vt.py from GB-1210. The guide's
// example ($1,800 weekly, married, 2 allowances -> $45.77) is in the tests.
// Civil union partners use the married table.
//
// W-4VT input: { filingStatus: "single" | "married" |
//   "marriedWithholdAtSingle", allowances, additionalWithholdingCents?,
//   exempt? }.
// No W-4VT: "An employer may use the information from federal form W-4 if a
// Vermont form is not submitted" - a pre-2020 W-4's marital status and
// allowances, or a 2020+ W-4's filing status (joint -> married) with no
// allowances; and "If the federal W-4 indicates an additional amount of
// federal withholding ... the Vermont withholding should be increased by
// 30% of the extra federal withholding." With no form at all: single, no
// allowances (the guide is silent; flagged).
//
// Wages: wages as defined under IRC 3401 (GB-1210), so pre-tax 401(k) is
// excluded.
//
// Not covered: the employee share of Vermont's Child Care Contribution (the
// 0.44% payroll tax; employers may withhold up to 0.11% from wages).

const { formChecker, onFile, PERIOD_BY_COUNT } = require("./formUtil");
const { fromBaseTable } = require("./brackets");

// Generated by tools/state/generate_vt.py (GB-1210-2026).
const PERCENTAGE_TABLES = Object.freeze({
  daily: Object.freeze({
    allowanceCents: 2077,
    single: Object.freeze([[0, 0, 0], [1510, 0, 335], [21030, 654, 660], [48760, 2484, 760], [100090, 6385, 875]]),
    married: Object.freeze([[0, 0, 0], [4530, 0, 335], [37110, 1091, 660], [83280, 4139, 760], [124550, 7275, 875]]),
  }),
  weekly: Object.freeze({
    allowanceCents: 10385,
    single: Object.freeze([[0, 0, 0], [7500, 0, 335], [105100, 3270, 660], [243800, 12424, 760], [500400, 31925, 875]]),
    married: Object.freeze([[0, 0, 0], [22600, 0, 335], [185500, 5457, 660], [416400, 20696, 760], [622700, 36375, 875]]),
  }),
  biweekly: Object.freeze({
    allowanceCents: 20769,
    single: Object.freeze([[0, 0, 0], [15100, 0, 335], [210300, 6539, 660], [487600, 24841, 760], [1000900, 63852, 875]]),
    married: Object.freeze([[0, 0, 0], [45300, 0, 335], [371100, 10914, 660], [832800, 41387, 760], [1245500, 72752, 875]]),
  }),
  semimonthly: Object.freeze({
    allowanceCents: 22500,
    single: Object.freeze([[0, 0, 0], [16400, 0, 335], [227800, 7082, 660], [528200, 26908, 760], [1084300, 69172, 875]]),
    married: Object.freeze([[0, 0, 0], [49100, 0, 335], [402000, 11822, 660], [902200, 44835, 760], [1349300, 78815, 875]]),
  }),
  monthly: Object.freeze({
    allowanceCents: 45000,
    single: Object.freeze([[0, 0, 0], [32700, 0, 335], [455600, 14167, 660], [1056500, 53827, 760], [2168500, 138339, 875]]),
    married: Object.freeze([[0, 0, 0], [98100, 0, 335], [804000, 23648, 660], [1804400, 89674, 760], [2698500, 157626, 875]]),
  }),
  quarterly: Object.freeze({
    allowanceCents: 135000,
    single: Object.freeze([[0, 0, 0], [98100, 0, 335], [1366900, 42505, 660], [3169400, 161470, 760], [6505600, 415021, 875]]),
    married: Object.freeze([[0, 0, 0], [294400, 0, 335], [2411900, 70936, 660], [5413100, 269015, 760], [8095600, 472885, 875]]),
  }),
  annual: Object.freeze({
    allowanceCents: 540000,
    single: Object.freeze([[0, 0, 0], [392500, 0, 335], [5467500, 170013, 660], [12677500, 645873, 760], [26022500, 1660093, 875]]),
    married: Object.freeze([[0, 0, 0], [1177500, 0, 335], [9647500, 283745, 660], [21652500, 1076075, 760], [32382500, 1891555, 875]]),
  }),
});

const TABLES = Object.freeze({
  2026: Object.freeze({
    percentageTables: PERCENTAGE_TABLES,
    federalExtraShareBp: 3_000,
    sources: Object.freeze([
      "Vermont Department of Taxes, GB-1210-2026 Income Tax Withholding Instructions, Tables, and Charts: https://tax.vermont.gov/sites/tax/files/documents/GB-1210-2026.pdf",
    ]),
  }),
});

function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("Vermont W-4VT");
  c.bool(form, "exempt");
  if (form.exempt) return;
  c.oneOf(form, "filingStatus", ["single", "married", "marriedWithholdAtSingle"]);
  c.nonNegInt(form, "allowances");
  c.cents(form, "additionalWithholdingCents");
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form, federalW4 = null }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  const table = period && t.percentageTables[period];
  if (!table) throw new Error(`Vermont has no percentage table for ${payPeriodsPerYear} pay periods a year`);
  const has = onFile(form);
  if (has && form.exempt) return { stateCents: 0, formBasis: "w-4vt-exempt", lines: {} };
  let status = "single";
  let allowances = 0;
  let extra = 0;
  let formBasis = "none-on-file-single-zero";
  if (has) {
    status = form.filingStatus === "married" ? "married" : "single";
    allowances = form.allowances ?? 0;
    extra = form.additionalWithholdingCents ?? 0;
    formBasis = "w-4vt";
  } else if (federalW4) {
    if (federalW4.formYear < 2020) {
      status = federalW4.maritalStatus === "married" ? "married" : "single";
      allowances = federalW4.allowances ?? 0;
      extra = Math.round(((federalW4.extraWithholdingCents ?? 0) * t.federalExtraShareBp) / 10_000);
    } else {
      status = federalW4.filingStatus === "marriedFilingJointly" ? "married" : "single";
      extra = Math.round(((federalW4.step4cExtraWithholdingCents ?? 0) * t.federalExtraShareBp) / 10_000);
    }
    formBasis = "federal-w4";
  }
  const net = Math.max(0, wagesCents - allowances * table.allowanceCents);
  const tax = fromBaseTable(net, table[status]);
  return {
    stateCents: Math.round(tax) + extra,
    formBasis,
    lines: { period, status, netCents: net },
  };
}

module.exports = {
  code: "VT",
  name: "Vermont",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
